module stop_counting (\n    input clk,\n    input rst_n,\n    input start,\n    input [31:0] arr_0, arr_1, arr_2, arr_3, arr_4, arr_5, arr_6, arr_7,\n    output reg done,\n    output reg [63:0] result_sum,\n    output reg [31:0] result_count\n);\n\n    // Parameters\n    localparam N = 8;\n    localparam SUM_WIDTH = 35;\n    localparam COUNT_WIDTH = 5;\n\n    // States\n    localparam [2:0] IDLE = 3'd0;\n    localparam [2:0] COMPUTE_PREFIX = 3'd1;\n    localparam [2:0] COMPUTE_SUFFIX = 3'd2;\n    localparam [2:0] SEARCH = 3'd3;\n    localparam [2:0] DONE = 3'd4;\n\n    // Registers\n    reg [2:0] state;\n    reg [3:0] i_ptr;\n    reg [3:0] j_ptr;\n    reg [3:0] i;\n    reg [3:0] j;\n    reg signed [SUM_WIDTH-1:0] best_sum;\n    reg [COUNT_WIDTH-1:0] best_count;\n    reg signed [SUM_WIDTH-1:0] pref [0:8];\n    reg signed [SUM_WIDTH-1:0] suff [1:9];\n    reg signed [31:0] arr [0:7];\n    integer k;\n\n    // Combinatorial values\n    wire signed [SUM_WIDTH-1:0] current_sum = pref[i] + suff[j];\n    wire [COUNT_WIDTH-1:0] current_count = i + (9 - j);\n\n    // Comparison logic\n    wire signed [63:0] lhs = current_sum * $signed({{(64-COUNT_WIDTH){1'b0}}, best_count});\n    wire signed [63:0] rhs = best_sum * $signed({{(64-COUNT_WIDTH){1'b0}}, current_count});\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result_sum <= 64'd0;\n            result_count <= 32'd0;\n            best_sum <= {SUM_WIDTH{1'b0}};\n            best_count <= {COUNT_WIDTH{1'b0}};\n            for (k = 0; k < 8; k = k + 1) arr[k] <= 32'd0;\n            for (k = 0; k <= 8; k = k + 1) pref[k] <= {SUM_WIDTH{1'b0}};\n            for (k = 1; k <= 9; k = k + 1) suff[k] <= {SUM_WIDTH{1'b0}};\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        arr[0] <= arr_0;\n                        arr[1] <= arr_1;\n                        arr[2] <= arr_2;\n                        arr[3] <= arr_3;\n                        arr[4] <= arr_4;\n                        arr[5] <= arr_5;\n                        arr[6] <= arr_6;\n                        arr[7] <= arr_7;\n                        i_ptr <= 0;\n                        state <= COMPUTE_PREFIX;\n                    end\n                end\n\n                COMPUTE_PREFIX: begin\n                    if (i_ptr == 0) begin\n                        pref[0] <= {SUM_WIDTH{1'b0}};\n                        i_ptr <= 1;\n                    end else if (i_ptr <= 8) begin\n                        pref[i_ptr] <= pref[i_ptr-1] + arr[i_ptr-1];\n                        i_ptr <= i_ptr + 1;\n                    end else begin\n                        j_ptr <= 9;\n                        state <= COMPUTE_SUFFIX;\n                    end\n                end\n\n                COMPUTE_SUFFIX: begin\n                    if (j_ptr == 9) begin\n                        suff[9] <= {SUM_WIDTH{1'b0}};\n                        j_ptr <= 8;\n                    end else if (j_ptr >= 1) begin\n                        suff[j_ptr] <= suff[j_ptr+1] + arr[j_ptr-1];\n                        j_ptr <= j_ptr - 1;\n                    end else begin\n                        i <= 0;\n                        j <= 1;\n                        best_sum <= 0;\n                        best_count <= 1;\n                        state <= SEARCH;\n                    end\n                end\n\n                SEARCH: begin\n                    if (current_count > 0) begin\n                        if ((i == 0 && j == 1) || (lhs > rhs)) begin\n                            best_sum <= current_sum;\n                            best_count <= current_count;\n                        end\n                    end\n\n                    if (j == 9) begin\n                        if (i == 8) begin\n                            state <= DONE;\n                        end else begin\n                            i <= i + 1;\n                            j <= i + 2;\n                        end\n                    end else begin\n                        j <= j + 1;\n                    end\n                end\n\n                DONE: begin\n                    done <= 1'b1;\n                    result_sum <= {{(64-SUM_WIDTH){1'b0}}, best_sum};\n                    result_count <= {{(32-COUNT_WIDTH){1'b0}}, best_count};\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule